void turret_draw_angle(int cx, int cy, int type, int angle_256, int is_selected) {
    if (type < 0 || type >= TURRET_TYPE_COUNT) type = 0;
    int angle_idx = ((angle_256 + 4) >> 3) & 31;

    const uint16_t *src = (type == TURRET_TYPE_LASCANNON) ? 
                          s_lascannon_angles[angle_idx] : 
                          s_heavy_bolter_angles[angle_idx];

    int ox = cx - 16;
    int oy = cy - 16;

    for (int y = 0; y < 32; y++) {
        int dst_y = oy + y;
        if (dst_y < 0 || dst_y >= SCREEN_H) continue;
        int row_idx = dst_y * SCREEN_W;
        int src_idx = y * 32;

        for (int x = 0; x < 32; x++) {
            int dst_x = ox + x;
            if (dst_x < 0 || dst_x >= SCREEN_W) continue;

            uint16_t col = src[src_idx + x];
            if (col & 0x8000) {
                g_backbuffer[row_idx + dst_x] = col;
            }
        }
    }

    if (is_selected) {
        renderer_draw_rect(ox - 1, oy - 1, 34, 34, COLOR_HAZARD_YELLOW);
    }
}
